        if (visited[current]) return false;
        visited[current] = true;

        var nextLevel = adj[current];
        foreach (var level in nextLevel) {
            adj[level].Remove(current);
            if (!DfsValidTree(adj, level, visited)) {
                return false;
            }
        }
        return true;
    }
}

